test("period claim counts scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "terms", "7");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  await ui.setSetting(pg_uma, "grace-days", "0");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  await ui.setSetting(pg_uma, "proof-threshold-B", "4.00");
  await ui.setSetting(pg_uma, "proof-kinds", "receipt,photo");
  await ui.setSetting(pg_uma, "clerk-limit-C", "9.00");
  await ui.setSetting(pg_uma, "score-mid", "0");
  await ui.setSetting(pg_uma, "score-high", "5");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C", "contact": "ADA@X"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "terms": "3", "tags": "b, a"}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Cam", "share": "33.33"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "33.33"})).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  await ui.refresh(pg_wes);
  expect(await ui.transfer(pg_wes, p_cam, `${sheet}-t`)).toBe(true);
  expect(await ui.search(pg_wes, "e")).toEqual([]);
  expect(await ui.importOpenings(pg_wes, "Ada,P2,1.00")).toBe(1);
  expect(await ui.pasteClaims(pg_wes, "Ada,12.50,,paste")).toBe(1);
  const c_ada_0 = await ui.claimAt(pg_wes, p_ada, 0);
  expect(await ui.remind(pg_wes, c_ada_0)).toBe(true);
  await ui.expectAuditView(pg_wes, "Ada", [
  ]);
  await ui.refresh(pg_wes);
  await ui.expectClaimTimeline(pg_wes, c_ada_0, [
  ]);
