import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, map, switchMap, tap } from 'rxjs';

export interface PeriodView {
  id: number;
  /** Unique on its sheet. */
  name: string;
  /** The first day of the period (yyyy-mm-dd), inclusive. */
  from: string;
  /** The last day of the period (yyyy-mm-dd), inclusive. */
  to: string;
  /** Whether the period is closed: no claim dated inside it can be added, edited or moved. */
  closed: boolean;
  /** Whether the period is soft-closed: its figures are fixed as for a close, but claims dated inside it can still
   *  be added and changed. Never true together with closed. */
  softClosed: boolean;
  /** The due-total fixed when the period was closed or soft-closed, with exactly two decimals; null while open. */
  closedTotal: string | null;
  /** Each person's due-total for the period, by person id, fixed when it was closed or soft-closed; empty while open. A person
   *  missing (added later) has 0.00. */
  closedPersonTotals: Record<string, string>;
  /** The most OPEN or PENDING claims a person may have in the period; null for no cap. */
  cap: number | null;
  /** Each person's carried figure for the period, by person id, fixed when it was closed or soft-closed; empty
   *  while open (absent from what was kept before figures were fixed). A person missing has 0.00. */
  closedPersonCarried?: Record<string, string> | null;
  /** Each person's opening balance for the period, by person id, added to their carried figure for it (absent from
   *  what was kept before openings were pasted). A person missing has 0.00. */
  personOpenings?: Record<string, string> | null;
  /** Whether a steward has locked the period: while locked it cannot be reopened (absent from what was kept before
   *  periods could be locked). */
  locked?: boolean;
}

/** A period as the form submits it: a blank from-date takes the sheet's today. */
export interface PeriodForm {
  name: string;
  from: string | null;
  to: string;
    <section aria-labelledby="periods-heading">
      <h2 id="periods-heading">Periods</h2>
      <ul aria-label="Periods of the sheet">
        @for (p of periods.list(); track p.id) {
          <li [attr.data-testid]="'period-row-' + p.name">
            <span data-testid="period-name">{{ p.name }}</span>
            from <span data-testid="period-from">{{ p.from }}</span>
            to <span data-testid="period-to">{{ p.to }}</span>
            — due <span data-testid="period-due-total">{{ (dueTotals().get(p.id) ?? '0.00') | figure }}</span>
            — <span data-testid="period-fy">{{ fiscalYearOf(p.from) }}</span>
            — cap <span data-testid="period-cap">{{ (p.cap ?? '') | figure }}</span>
            — closed <span data-testid="period-closed">{{ p.closed ? 'yes' : p.softClosed ? 'soft' : 'no' }}</span>
            <button type="button" data-testid="period-close" (click)="close(p)" [disabled]="closing() === p.id"
                    [attr.aria-label]="'Close period ' + p.name">Close</button>
            <button type="button" data-testid="period-soft-close" (click)="softClose(p)" [disabled]="closing() === p.id"
                    [attr.aria-label]="'Soft-close period ' + p.name">Soft close</button>
            <button type="button" data-testid="period-reopen" (click)="reopen(p)" [disabled]="closing() === p.id"
                    [attr.aria-label]="'Reopen period ' + p.name">Reopen</button>
            — locked <span data-testid="period-locked">{{ p.locked ? 'yes' : 'no' }}</span>
            <button type="button" data-testid="period-lock" (click)="setLocked(p, true)" [disabled]="closing() === p.id"
                    [attr.aria-label]="'Lock period ' + p.name">Lock</button>
            <button type="button" data-testid="period-unlock" (click)="setLocked(p, false)" [disabled]="closing() === p.id"
                    [attr.aria-label]="'Unlock period ' + p.name">Unlock</button>
            @if (periodError()?.id === p.id) {
              <p role="alert" data-testid="period-error">{{ periodError()?.message }}</p>
            }

